ROOT.scriptdef:
CREATE TRIGGER [CDN].[InwArkTwr_DeletePrzenumeruj] ON [CDN].[InwArkTwr] FOR DELETE AS BEGIN SET NOCOUNT ON;
With IAT As ( SELECT I.IAT_Id as IAT_Id, ROW_NUMBER() OVER (PARTITION BY IAT_InAId ORDER BY [IAT_InALp] ASC) AS RowNum, I.IAT_InALp as IAT_InALp FROM cdn.InwArkTwr I WHERE I.IAT_Id not in (SELECT D.IAT_Id FROM Deleted D) AND I.IAT_InAId in (SELECT D.IAT_InAId FROM Deleted D) ) UPDATE IAT SET IAT.IAT_InALp=RowNum
SET NOCOUNT OFF END
